/** Languages shown in the UI. Labels are written in their own language. */
export const languageOptions = [
  { code: 'ru', label: 'Русский' },
  { code: 'en', label: 'English' },
  { code: 'de', label: 'Deutsch' },
  { code: 'es', label: 'Español' },
  { code: 'pt-BR', label: 'Português (Brasil)' },
  { code: 'fr', label: 'Français' },
  { code: 'tr', label: 'Türkçe' },
  { code: 'fa', label: 'فارسی' },
  { code: 'ar', label: 'العربية' },
  { code: 'zh-CN', label: '简体中文' },
  { code: 'uk', label: 'Українська' },
  { code: 'pl', label: 'Polski' },
] as const

export type UILanguage = (typeof languageOptions)[number]['code']

/**
 * Check whether a value is one of the supported interface language codes.
 * @param value - The candidate language code.
 * @returns Whether the value can be used as a UI language.
 */
export function isUILanguage(value: string | null): value is UILanguage {
  return languageOptions.some(option => option.code === value)
}

/**
 * Merge localized overrides with the complete English catalog.
 * @param overrides - Messages translated for the target locale.
 * @returns A complete translation catalog with English fallback strings.
 */
function localized(overrides: Partial<TranslationMessages>): TranslationMessages {
  return { ...en, ...overrides }
}

